T = {}
T[0] = "Harness VLA：用记忆引导的 Agent 把冻结 VLA 变成可靠的操作原语"
T[1] = "通讯作者"
T[2] = "图 1：Harness VLA 系统概览。给定任务描述、RGB-D 观测与机器人状态，agentic 规划器从一个固定的原语库中选择结构化调用，而不是直接输出低层动作。原语库把冻结的 VLA 暴露为用于接触密集行为的 VLA ACT，并用 MOVE TO、ROTATE、SET GRIPPER 等解析原语完成感知条件化的预定位、搬运、姿态调整与释放。任务专属记忆（Task Specific Memory）存储来自参考种子探索的成功命令轨迹以供少样本重新 grounding，全局记忆（Global Memory）存储可复用的成功规则与失败模型。右侧面板汇总了相对各自最强基线的提升，底部条带展示了一次在稀疏 VLA 调用与解析控制之间交替的 rollout。"
T[3] = "摘要"
T[4] = "语言条件操作既需要精确的接触密集控制，也需要对语言、场景与长程的鲁棒推理。端到端的视觉-语言-动作（VLA）模型提供了强大的局部视觉运动技能，但它们在分布内的任务轨迹上训练，在部署扰动下——语义重定向、目标重绑定、空间布局变化、不稳定的局部接触——常常退化。LLM coding agent 提供了互补的语义与组合推理，但纯解析原语难以处理不规则抓取、受限放置与铰接物体交互。我们提出 Harness VLA，一个记忆增强的 agentic 框架：把冻结的 VLA 暴露为一个可重试的接触密集原语，并把它与一个小而固定的解析原语库（用于 grounding、预定位、搬运、导航与释放）组合。harness 不扩张技能库，而是从任务专属执行轨迹、全局成功规则与失败模型中学习这些固定原语的适用范围。通过把语义重新 grounding、非接触执行与 VLA 重新预定位上提到规划器，同时把冻结 VLA 保留给局部的接触密集阶段，Harness VLA 无需微调即把预训练 VLA 扩展到其原始轨迹分布之外。在扰动桌面、家居厨房与从干净到随机化的双臂操作上，Harness VLA 相对各自最强基线在 LIBERO-Pro 与 RoboCasa365 上分别提升⟦0⟧与⟦1⟧个百分点，并在 RoboTwin C2R 上达到⟦2⟧。代码见 ⟦3⟧。"
T[5] = "1 引言"
T[6] = "机器人操作的一个长期目标，是一个能在变化的物体、布局与本体上可靠执行自由形式自然语言指令的系统。两种主导范式从相反方向接近这个目标：端到端的视觉-语言-动作（VLA）模型直接从机器人轨迹学习接触密集的视觉运动控制，而 LLM coding agent 用语言模型推理来组合显式的感知与控制 API。两种范式各有威力，却都把过多的责任分给了错误的组件：单体 VLA 必须在单一策略内同时吸收语言 grounding、长程组合与低层控制，而 coding agent 必须通过人工设计或 agent 生成的 API 实现物理上精细的交互。图 2 直观展示了我们的回应：用解析原语穿越部署扰动，只在训练分布有信息量的局部接触密集区域内调用 VLA。端到端 VLA 模型进展迅速，从通用机器人策略 ⟦0⟧ 到流匹配与动作推理架构 ⟦1⟧。它们的强项是局部的、以图像为条件的接触：抓取不规则物体、以紧公差放置、操作对解析控制器而言脆弱的固定装置。它们的弱项是在训练轨迹分布之外的部署。一个在分布内任务轨迹上训练的模型也许知道怎样抓牛奶盒或转水龙头，却会在语义目标被重定向、目标谓词被重绑定、物体布局变化或短技能需要组合成更长流程时失败。在这类部署扰动下，策略可能在指令或场景绑定已经改变时仍重复熟悉的训练时行为 ⟦2⟧；一次不稳定的接触失败也可能让整个单体 rollout 脱轨。LLM coding agent 与 harness 提供了互补的语义与组合推理。Code as Policies 与 ProgPrompt 之类的系统在精选的感知与控制 API 之上合成可执行程序 ⟦3⟧，近期的多模态或 agentic 变体用更丰富的感知、工具使用、反馈与持久执行状态扩展了这一思想 ⟦4⟧。更广泛地说，coding-agent harness 把模型输出包裹在一个带工具接口、记忆、验证器、执行循环与反馈通道的结构化运行时中，使 agent 能修订决策、把成功轨迹或失败诊断写回记忆，并在共同的控制面下编排异构工具 ⟦5⟧。然而在机器人操作中，扩展此类系统往往仍意味着扩张原语或技能库，而纯解析"
T[7] = "原语——确定性的运动学或基于模型的控制器，如 IK 搬运、腕部旋转、底盘运动、夹爪张开与释放——仍然不适合不规则抓取、受限放置与铰接物体操作。"
T[8] = "Harness VLA 把这种 coding-agent harness 观点实例化到机器人操作上：保持原语库固定且小，让 agent 学习如何编排它。规划器为非接触结构组合解析原语——目标 grounding、自由空间搬运、姿态调整、移动预定位、失败尝试后的重新预定位与释放；对于接触密集阶段，它通过单个学习到的原语 VLA ACT 调用冻结的 VLA。这把 VLA 从单体轨迹策略转变为可复用的接触专家，无需微调或部署时扩张原语即可把它扩展到原始轨迹分布之外的任务。关键不仅在于暴露 VLA ACT，还在于学习何时以及如何"
